// Guard: payload must be a non-null object
if (!msg.payload || typeof msg.payload !== 'object') {
    node.warn('Non-object payload on ' + msg.topic + ': ' + JSON.stringify(msg.payload));
    return null;
}

var data   = msg.payload;
var temp   = (data.temperature !== undefined && data.temperature !== null)
               ? Number(data.temperature) : null;
var humid  = (data.humidity !== undefined && data.humidity !== null)
               ? Number(data.humidity) : null;
var device = data.device_id ? String(data.device_id) : 'unknown';

// Output 1: numeric temperature to ui_gauge
var tempMsg = null;
if (temp !== null && !isNaN(temp)) {
    tempMsg = { payload: temp };
}

// Output 2: numeric humidity to ui_gauge
var humidMsg = null;
if (humid !== null && !isNaN(humid)) {
    humidMsg = { payload: humid };
}

// Output 3: device ID string to ui_text
// Only update Active Device if this device is NOT in the blocked list
var blocked = flow.get('blockedDevices') || {};
var deviceMsg = null;
if (!blocked[device]) {
    deviceMsg = { payload: device };
}

return [tempMsg, humidMsg, deviceMsg];

var a = msg.payload || {};
var type     = String(a.alert_type || 'UNKNOWN');
var severity = String(a.severity   || 'WARNING');
var ts       = String(a.timestamp  || new Date().toISOString());
var device   = String(a.device_id  || a.source || '-');
var reason   = String(a.reason     || a.detail || JSON.stringify(a).substring(0, 100));

// Colour by severity
var color;
if      (severity === 'CRITICAL') { color = '#e63946'; }
else if (severity === 'WARNING')  { color = '#f4a261'; }
else                              { color = '#2a9d8f'; }

// HH:MM:SS from ISO timestamp
var timeStr = (ts.length > 19) ? ts.substring(11, 19) : ts;

// Output 1 → counter increment (payload=1, counter fn adds it up)
var countMsg = { payload: 1 };

// Output 2 → latest alert ui_text (payload MUST be string)
var latestMsg = { payload: '[' + severity + '] ' + type + ' — ' + reason };

// Output 3 → security status ui_text (payload MUST be string)
var statusMsg = { payload: severity + ' — ' + type };

// Output 4 → alert log accumulator (carries row fields as top-level props)
var tableMsg = {
    payload:  timeStr + ' | ' + severity + ' | ' + type + ' | ' + device + ' | ' + reason,
    timeStr:  timeStr,
    severity: severity,
    type:     type,
    device:   device,
    reason:   reason,
    color:    color
};

return [countMsg, latestMsg, statusMsg, tableMsg];

var count = context.get('count') || 0;
if (msg.payload === 'RESET') {
    count = 0;
    context.set('count', count);
    msg.payload = String(count);
    return msg;
}
count = count + 1;
context.set('count', count);
msg.payload = String(count);
return msg;

// Build and store up to 50 alert rows in flow context
var rows = flow.get('alertRows') || [];
rows.unshift({
    timeStr:  msg.timeStr  || '-',
    severity: msg.severity || '-',
    type:     msg.type     || '-',
    device:   msg.device   || '-',
    reason:   msg.reason   || '-'
});
if (rows.length > 50) rows = rows.slice(0, 50);
flow.set('alertRows', rows);
msg.rows = rows;
return msg;

var d = msg.payload || {};
var status = d.status || 'unknown';

// Use the blocklist to hide rogue devices
var blocked = flow.get('blockedDevices') || {};
var allDevices = Array.isArray(d.connected_devices) ? d.connected_devices : [];
var cleanDevices = allDevices.filter(function(id) { return !blocked[id]; });

// Count: prefer cleaned list length; fall back to d.device_count minus blocked matches
var rawCount = (d.device_count !== undefined) ? Number(d.device_count) : allDevices.length;
var blockedInList = allDevices.length - cleanDevices.length;
var devices = Math.max(0, rawCount - blockedInList);

// Known Devices list: use cleaned list if available, else just show count
var devList;
if (cleanDevices.length > 0) {
    devList = cleanDevices.join(', ');
} else if (devices > 0) {
    devList = devices + ' device(s) connected';
} else {
    devList = 'none';
}

// Output 1: engine online/offline string
var statusMsg  = { payload: (status === 'online') ? 'ONLINE' : 'OFFLINE' };

// Output 2: device count (blocked devices excluded)
var deviceMsg  = { payload: String(devices) };

// Output 3: comma-separated clean device list
var devListMsg = { payload: devList };

return [statusMsg, deviceMsg, devListMsg];

// Sliding 2-second window
var now = Date.now();
var counts = flow.get("msgCounts") || [];

counts.push(now);

// Keep only last 2 seconds
counts = counts.filter(function (t) {
    return now - t < 2000;
});

flow.set("msgCounts", counts);

var rate = Math.round(counts.length / 2);

// Save flood detection time
if (rate > 100) {
    flow.set("lastFlood", now);
}

var lastFlood = flow.get("lastFlood") || 0;

var status;

// Keep warning visible for 10 seconds
if (now - lastFlood < 10000) {
    status = "🚨 FLOOD DETECTED : " + rate + " msg/s";
}
else {
    status = "Normal : " + rate + " msg/s";
}

return [
    { payload: rate, topic: "msg/s" },
    { payload: status }
];

// Push sensible defaults to every widget on startup
// ui_text requires string payloads; ui_gauge requires numbers
var alertCount = { payload: '0' };
var latest     = { payload: 'No alerts yet — system is monitoring' };
var secStatus  = { payload: 'OK — No threats detected' };
var engine     = { payload: 'OFFLINE' };
var devCount   = { payload: '0' };
var flood      = { payload: 'Normal: 0 msg/s' };
return [[alertCount], [latest], [secStatus], [engine], [devCount], [flood]];

// Clear flow context alertRows
flow.set('alertRows', []);
// Clear flow context msgCounts (for rate monitor)
flow.set('msgCounts', []);
flow.set('lastFlood', 0);

var alertReset = { payload: 'RESET' };
var latest     = { payload: 'No alerts yet — system is monitoring' };
var secStatus  = { payload: 'OK — No threats detected' };
var devCount   = { payload: '1' };
var devList    = { payload: 'pico-001' };
var flood      = { payload: 'Normal : 0 msg/s' };
var tableMsg   = { rows: [], payload: [] };
var activeDev  = { payload: 'pico-001' };

return [alertReset, latest, secStatus, devCount, devList, flood, tableMsg, activeDev];

// Determine which attack was blocked from the topic
var topic = msg.topic || '';
var label;
var rogueId = null;
if      (topic.indexOf('rogue')     !== -1) { label = 'Rogue Device';      rogueId = msg._rogueId || 'rogue-device-99'; }
else if (topic.indexOf('flood')     !== -1) { label = 'Flood Attack'; }
else if (topic.indexOf('fake_data') !== -1) { label = 'Fake Sensor Data'; }
else                                         { label = 'Attack'; }

// Register blocked device IDs so Extract sensor fields ignores them
if (rogueId) {
    var blocked = flow.get('blockedDevices') || {};
    blocked[rogueId] = true;
    // Also block common rogue IDs generically
    blocked['rogue-device-99'] = true;
    flow.set('blockedDevices', blocked);
}

var ts = new Date().toLocaleTimeString();

// ISO for row timeStr (HH:MM:SS)
var now = new Date();
var timeStr = now.toTimeString().substring(0, 8);

// Output 1 -> Security Status widget
var statusMsg = { payload: 'BLOCKED — ' + label + ' stopped at ' + ts };

// Output 2 -> Latest Alert widget
var latestMsg = { payload: '[BLOCKED] ' + label + ' — mitigation applied at ' + ts };

// Output 3 -> Reset Active Device back to the legitimate device
var deviceMsg = { payload: 'pico-001' };

// Output 4 -> Inject a BLOCKED row into the alert log (keeps existing rows)
var tableMsg = {
    payload:  timeStr + ' | INFO | BLOCKED | dashboard | ' + label + ' attack stopped',
    timeStr:  timeStr,
    severity: 'INFO',
    type:     'BLOCKED',
    device:   'dashboard',
    reason:   label + ' attack stopped by operator',
    color:    '#2a9d8f'
};

return [statusMsg, latestMsg, deviceMsg, tableMsg];

var a = msg.payload || {};

msg.topic = '🚨 IoT Cyberattack Detected';

msg.payload =
'IoT Cyberattack Detection System\n\n' +
'Attack Type : ' + (a.alert_type || 'Unknown') + '\n' +
'Severity    : ' + (a.severity || 'Unknown') + '\n' +
'Device ID   : ' + (a.device_id || '-') + '\n' +
'Reason      : ' + (a.reason || '-') + '\n' +
'Timestamp   : ' + (a.timestamp || new Date().toLocaleString()) + '\n\n' +
'This alert was generated automatically by the IoT Cyberattack Detection Engine.\n\n' +
'Please investigate immediately.';

return msg;

var a = msg.payload || {};

var type = a.alert_type || "UNKNOWN_ATTACK";
var severity = a.severity || "WARNING";
var device = a.device_id || "-";
var reason = a.reason || "Cyberattack detected";

msg.payload =
    "🚨 IoT Cyberattack Detected\n\n" +
    "Severity: " + severity + "\n" +
    "Attack: " + type + "\n" +
    "Device: " + device + "\n" +
    "Reason: " + reason;

return msg;
